// The printed flyer is the only part of this system a family touches before
// the app exists for them. A QR that lands them in the wrong language is worse
// than no QR: they have already decided the app is not for them.

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const src = readFileSync(new URL('../../qr.js', import.meta.url), 'utf8');

test('the flyer QR carries the language as well as the class code', () => {
  // Both halves of the sheet are generated by the same function, so the
  // language must come from its argument rather than a constant.
  assert.match(src, /lang=\$\{lang\}/, 'the QR target does not include the language');
  assert.match(src, /class=\$\{encodeURIComponent\(classCode\)\}/, 'the QR target lost the class code');
});

test('both language halves are rendered from the same builder', () => {
  assert.match(src, /flyer\('en',/, 'no English flyer');
  assert.match(src, /flyer\('es',/, 'no Spanish flyer');
});
